import {useState,useEffect} from 'react';
import {useTemplateRuntime} from './template-runtime.jsx';
import Page0 from './pages/Page0.jsx';
import Page1 from './pages/Page1.jsx';
import Page2 from './pages/Page2.jsx';
import Page3 from './pages/Page3.jsx';
import Page4 from './pages/Page4.jsx';
import Page5 from './pages/Page5.jsx';
import Page6 from './pages/Page6.jsx';
import Page7 from './pages/Page7.jsx';
import Page8 from './pages/Page8.jsx';
import Page9 from './pages/Page9.jsx';
import Page10 from './pages/Page10.jsx';
import Page11 from './pages/Page11.jsx';
const pages={"demo-corporate-1":Page0,"demo-corporate-1-about":Page1,"demo-corporate-1-article":Page2,"demo-corporate-1-careers":Page3,"demo-corporate-1-case-studies":Page4,"demo-corporate-1-case-study":Page5,"demo-corporate-1-contact":Page6,"demo-corporate-1-faq":Page7,"demo-corporate-1-insights":Page8,"demo-corporate-1-service":Page9,"demo-corporate-1-services":Page10,"demo-corporate-1-team":Page11};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-corporate-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-corporate-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

